const sandWolfSheet=new Image();sandWolfSheet.assetSrc='assets/desert-sand-wolf-v1.png';
function beginSandWolf(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy)||1,target={x:p.x+dx/len*60,y:p.y+dy/len*60};if(!passable(target.x,target.y,18)||!lineClear(e,target,18))target={x:p.x,y:p.y};if(!passable(target.x,target.y,18)||!lineClear(e,target,18))return false;e.state='attack';e.elapsed=0;e.struck=false;e.facing=dx-dy<0?-1:1;e.attack={pattern:'sandBurrow',bespoke:true,windup:1.15,origin:{x:e.x,y:e.y},target,moved:false,landed:false,bitten:false};return true;}
const sandWolfAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r4e0')return sandWolfAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='sandBurrow'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=260&&clear&&beginSandWolf(e)){}else{e.state='idle';if(distance>750&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,112*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;let a=e.attack;
 if(!a.moved&&e.elapsed>=.9){a.moved=true;if(dist(e,a.target)<=360&&lineClear(e,a.target,18)&&passable(a.target.x,a.target.y,18)){for(let i=0;i<40;i++){let dx=a.target.x-e.x,dy=a.target.y-e.y,len=Math.hypot(dx,dy);if(len<.01)break;let step=Math.min(10,len);if(moveActor(e,dx/len*step,dy/len*step,18)<step*.5)break;}a.landed=dist(e,a.target)<=12;}burst(e.x,e.y,42,'#d7b97f');playSound('impact',e.x,e.y);}
 if(!a.bitten&&e.elapsed>=1.15){a.bitten=true;e.struck=true;if(a.landed&&dist(e,a.target)<=12&&dist(p,a.target)<=75+1e-8&&lineClear(a.target,p))hurt(54);playSound('slash',e.x,e.y);}
 if(e.elapsed>=1.9){e.attack=null;e.state='idle';e.t=2.2;}
};
const sandWolfDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e0'||!sandWolfSheet.complete||!sandWolfSheet.naturalWidth)return sandWolfDrawBase(e,size);let f=spriteFrame(e.state,e.anim);if(e.attack?.pattern==='sandBurrow')f={row:2,col:e.elapsed<.45?0:e.elapsed<.9?1:e.elapsed<1.15?2:3};let q=project(e.x,e.y),sw=sandWolfSheet.naturalWidth/4,sh=sandWolfSheet.naturalHeight/3,w=125,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.88,w,h);else ctx.drawImage(sandWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.88,w,h);ctx.restore();return true;};
const sandWolfSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e0'?92:sandWolfSizeBase(e);
const sandWolfGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandWolfGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e0'):enemies)){let a=e.attack;if(e.species!=='r4e0'||e.hp<=0||a?.pattern!=='sandBurrow'||!visibleAt(a.target.x,a.target.y))continue;if(!a.bitten){groundRing(a.target.x,a.target.y,75,'#ffc574',2);groundRing(a.target.x,a.target.y,75*Math.min(1,e.elapsed/1.15),'#edc88b',1);}else if(e.elapsed<1.35&&a.landed)groundRing(a.target.x,a.target.y,75,'#ffe9bd',3);}};
